  const quickLinks = (content?.quick_links as { label: string; url: string }[]) ?? [];

  return (
    <>
      <Breadcrumbs
        crumbs={[
          { label: 'dashboard', href: '/dashboard' },
          { label: `${name} wiki`, href: base },
          { label: 'Getting Started' },
