                    }}
                  >
                    {entity.file}:{entity.line}
                  </span>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {letters.length === 0 && (
        <InfoBox variant="info">No public API entities found.</InfoBox>
      )}
    </>
  );
}

